class Queue:
    def __init__(self):
        self.stack1 = []
        self.stack2 = []

    def enqueue(self, item):
        # Add item to stack 1
        while not len(self.stack2) == 0:
            self.stack1.append(self.stack2.pop())
        self.stack2.append(item)
        # Add item to stack 2
        while not len(self.stack1) == 0:
            self.stack2.append(self.stack1.pop())

    def dequeue(self):
        if not len(self.stack2):
            while not len(self.stack1) == 0:
                self.stack2.append(self.stack1.pop())
        return self.stack2.pop()

    def size(self):
        return len(self.stack2)

# Example usage
q = Queue()
q.enqueue(1)
q.enqueue(2)
q.enqueue(3)
print(q.dequeue())  # Output: 3
print(q.size())  # Output: 2
```

In this implementation, we use two stacks (`stack1` and `stack2`) to store the elements of the queue. We start by adding items to both stacks. Then, we add items from the second stack to the first stack until it becomes empty. Finally, we remove items from the first stack until it becomes empty. The resulting stack contains all the elements of the queue.
